import csv, io, json, os, re, sys, unicodedata


def norm_id(s):
    return str(s).strip().lower()


def norm_text(s):
    s = s.casefold()
    s = ''.join(ch if ch.isalnum() else ' ' for ch in s)
    return ' '.join(s.split())


def read_batch(path):
    """Return (batch, revision, status, records[(ballot, contest, {rank:[marks]})])
    where a mark is ('c', id) or ('w', text)."""
    with open(path, encoding='utf-8-sig', newline='') as f:
        text = f.read()
    records = []
    if path.endswith('.jsonl'):
        head = None
        for line in text.split('\n'):
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            if head is None:
                head = obj
                continue
            ranks = {}
            for m in obj.get('marks', []):
                r = int(m['rank'])
                if m.get('write_in') is not None:
                    mark = ('w', m['write_in'])
                elif m.get('candidate') is not None:
                    mark = ('c', m['candidate'])
                else:
                    continue
                ranks.setdefault(r, []).append(mark)
            records.append((obj['ballot'], obj['contest'], ranks))
        meta = head or {}
    else:
        meta = {}
        lines = text.split('\n')
        i = 0
        while i < len(lines):
            l = lines[i].strip()
            if l.startswith('#'):
                m = re.match(r'#\s*([^:]+?)\s*:\s*(.*)$', l)
                if m:
                    meta[m.group(1).strip().lower()] = m.group(2).strip()
                i += 1
            elif not l:
                i += 1
            else:
                break
        rows = csv.reader(io.StringIO('\n'.join(lines[i:])))
        header = None
        for row in rows:
            if not row or all(not c.strip() for c in row):
                continue
            if header is None:
                header = [c.strip() for c in row]
                continue
            d = dict(zip(header, row))
            ranks = {}
            for k, v in d.items():
                m = re.fullmatch(r'rank(\d+)', k)
                if not m or v is None:
                    continue
                marks = []
                for part in v.split('|'):
                    p = part.strip()
                    if not p:
                        continue
                    if p[:3].upper() == 'WI:':
                        marks.append(('w', p[3:]))
                    else:
                        marks.append(('c', p))
                if marks:
                    ranks[int(m.group(1))] = marks
            records.append((d['ballot'].strip(), d['contest'].strip(), ranks))
    return (str(meta['batch']), int(str(meta['revision']).strip()),
            str(meta.get('status', 'final')).strip().lower(), records)


def read_ballot(ranks, contest, qual, status):
    """Return list of items, one per ranking 1..max_ranks."""
    seen = set()
    items = []
    for r in range(1, contest['max_ranks'] + 1):
        marks = set()
        for kind, v in ranks.get(r, []):
            if kind == 'w':
                c = qual.get(norm_text(v))
                if c is not None:
                    marks.add(c)
            else:
                marks.add(norm_id(v))
        if not marks:
            items.append(('skip',))
            continue
        marks = {m for m in marks if status.get(m) != 'withdrawn'}
        if not marks:
            items.append(('pass',))
            continue
        prior = seen
        seen = seen | marks
        marks = marks - prior
        if not marks:
            items.append(('skip',))
        elif len(marks) == 1:
            items.append(('choice', next(iter(marks))))
        else:
            items.append(('over',))
    return items


def count_for(items, continuing):
    n = len(items)
    for i, it in enumerate(items):
        k = it[0]
        if k == 'choice':
            if it[1] in continuing:
                return it[1]
        elif k == 'skip':
            if i + 1 < n and items[i + 1][0] == 'skip':
                return None
        # pass / over: go on
    return None


def run_contest(contest, ballots_items):
    ids = {}
    order = []
    for c in contest['candidates']:
        ids[norm_id(c['id'])] = c['id']
    for w in contest.get('write_ins', []):
        ids[norm_id(w['id'])] = w['id']
    status = {norm_id(c['id']): c.get('status', 'active') for c in contest['candidates']}
    continuing = {k for k in ids if status.get(k) != 'withdrawn'}
    lot = [norm_id(x) for x in contest.get('lot_order', [])]
    total = len(ballots_items)
    rounds = []
    history = []  # per round dict of votes
    winner = None
    while True:
        votes = {c: 0 for c in continuing}
        active = 0
        for items in ballots_items:
            c = count_for(items, continuing)
            if c is not None:
                votes[c] += 1
                active += 1
        rd = {'round': len(rounds) + 1,
              'tallies': {ids[c]: votes[c] for c in votes},
              'exhausted': total - active, 'eliminated': []}
        rounds.append(rd)
        history.append(votes)
        if active == 0:
            break
        win = None
        for c, v in votes.items():
            if v * 2 > active:
                win = c
        if win is None and len(continuing) == 1:
            win = next(iter(continuing))
        if win is not None:
            winner = ids[win]
            break
        zeros = [c for c in continuing if votes[c] == 0]
        if zeros:
            elim = zeros
        else:
            m = min(votes.values())
            tied = [c for c in continuing if votes[c] == m]
            r = len(history) - 2
            while len(tied) > 1 and r >= 0:
                mm = min(history[r][c] for c in tied)
                tied = [c for c in tied if history[r][c] == mm]
                r -= 1
            if len(tied) > 1:
                tied.sort(key=lambda c: lot.index(c) if c in lot else -1)
                tied = [tied[-1]]
            elim = tied
        rd['eliminated'] = sorted(ids[c] for c in elim)
        continuing -= set(elim)
    return {'contest': contest['id'], 'ballots': total, 'winner': winner, 'rounds': rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, 'election.json'), encoding='utf-8-sig') as f:
        election = json.load(f)
    cvr = os.path.join(indir, 'cvr')
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        b, rev, st, recs = read_batch(p)
        if b not in best or rev > best[b][0]:
            best[b] = (rev, st, recs)
    per = {c['id']: [] for c in election['contests']}
    cmap = {}
    for c in election['contests']:
        qual = {}
        for w in c.get('write_ins', []):
            for t in [w['name']] + list(w.get('aliases', [])):
                qual[norm_text(t)] = norm_id(w['id'])
        status = {norm_id(x['id']): x.get('status', 'active') for x in c['candidates']}
        cmap[c['id']] = (c, qual, status)
    for b in sorted(best):
        rev, st, recs = best[b]
        if st != 'final':
            continue
        for ballot, cid, ranks in recs:
            if cid in cmap:
                c, qual, status = cmap[cid]
                per[cid].append(read_ballot(ranks, c, qual, status))
    out = {'election': election['election'],
           'contests': [run_contest(c, per[c['id']]) for c in election['contests']]}
    with open(outfile, 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=1)


main()
